def stl_triangles(path):
    dt = np.dtype([('normal', '<f4', (3,)), ('vertices', '<f4', (3, 3)), ('attr', '<u2')])
    with path.open('rb') as f:
        f.read(80)
        count = int(np.frombuffer(f.read(4), dtype='<u4')[0])
        return np.frombuffer(f.read(), dtype=dt, count=count)['vertices']
